ROOT_TEXT = "静脉输液（JMSY2）操作流程｜6 环节 · 13 步骤 · 40 操作"


def build():
    """返回 [(text, children, color)] 三层树"""
    tree = []
    for idx, (qn, qnm, qs, stage, steps) in enumerate(CFG):
        color = PALETTE[idx % len(PALETTE)]
        s_nodes = []
        for sn, snm, ss, ops in steps:
            o_nodes = [("%s %s（%s分）" % (on, onm, os_), [], None) for on, onm, os_ in ops]
            s_nodes.append(("%s %s（%s分）" % (sn, snm, ss), o_nodes, None))
        tree.append(("%s %s（%s分｜%s）" % (qn, qnm, qs, stage), s_nodes, color))
    return tree


def stats(tree):
    return (len(tree),
            sum(len(x[1]) for x in tree),
            sum(len(y[1]) for x in tree for y in x[1]))


# ------------------------------------------------------------------ FreeMind
def make_mm(tree, path):
    root_map = ET.Element("map", {"version": "1.0.1"})

    def add(parent, text, children, color, level):
        attrs = {"TEXT": text}
        if level == 0:
            attrs["COLOR"] = "#FFFFFF"
            attrs["BACKGROUND_COLOR"] = "#243447"
        elif level == 1:
            attrs["COLOR"] = "#FFFFFF"
            attrs["BACKGROUND_COLOR"] = color
        else:
            attrs["COLOR"] = "#1F2937" if level == 2 else "#3B4757"
        node = ET.SubElement(parent, "node", attrs)
        if level <= 2:
            ET.SubElement(node, "font", {
                "NAME": "Microsoft YaHei",
                "SIZE": "16" if level == 0 else ("13" if level == 1 else "12"),
                "BOLD": "true" if level <= 2 else "false",
            })
        ET.SubElement(node, "edge", {
            "COLOR": color if level <= 1 else "#9CA3AF",
            "WIDTH": "2" if level == 1 else "thin",
        })
        for c in children:
            add(node, c[0], c[1], color, level + 1)
        return node

    r = add(root_map, ROOT_TEXT, tree, PALETTE[0], 0)
    for n in list(r):
        if n.tag == "node":
            n.set("POSITION", "right")
            n.set("FOLDED", "false")
    ET.indent(root_map, space="  ")
    with open(path, "wb") as f:
        f.write(ET.tostring(root_map, encoding="utf-8", xml_declaration=True))
    return path


