    opml = ET.Element("opml", {"version": "1.0"})
    ET.SubElement(ET.SubElement(opml, "head"), "title").text = "静脉输液（JMSY2）操作流程"
    body = ET.SubElement(opml, "body")

    def add(parent, text, children):
        node = ET.SubElement(parent, "outline", {"text": text})
        for c in children:
            add(node, c[0], c[1])
        return node

    add(body, ROOT_TEXT, tree)
    ET.indent(opml, space="  ")
    with open(path, "wb") as f:
        f.write(ET.tostring(opml, encoding="utf-8", xml_declaration=True))
    return path


