                           % (cls, html.escape(text), render(children, depth + 1, color)))
            else:
                out.append('<li class="%s"><span class="t">%s</span></li>'
                           % (cls, html.escape(text)))
        out.append("</ul>")
        return "".join(out)

    q, s, o = stats(tree)
