.wrap{background:#fff;border:1px solid #E3E8EF;border-radius:10px;padding:18px 22px;
      box-shadow:0 1px 3px rgba(16,24,40,.05)}
ul{list-style:none;margin:0;padding-left:20px;border-left:1px dashed #D6DEE9}
