body > .wrap > ul{border-left:none;padding-left:0}
body > .wrap > ul > li{padding-left:0}
body > .wrap > ul > li::before{display:none}
.t{display:inline-block}
.l1 > .t{background:#243447;color:#fff;font-weight:700;font-size:14px;
         padding:5px 14px;border-radius:6px}
